import { App } from './App'
import { ChatClient } from './data/client'
import { STORAGE_KEYS } from './data/storage'
import { FakeFetch, MemoryStorage } from './data/testSupport'
import type { FakeCall } from './data/testSupport'
import { local, uuid, wire } from './domain/testMessages'
import type { LocalMessage } from './domain/types'

let clients: ChatClient[] = []

function setup(seed: { identity?: string; messages?: LocalMessage[]; outbox?: string[] } = {}) {
  const storage = new MemoryStorage()
  if (seed.identity) storage.data.set(STORAGE_KEYS.identity, seed.identity)
  if (seed.messages) storage.data.set(STORAGE_KEYS.messages, JSON.stringify(seed.messages))
  if (seed.outbox) storage.data.set(STORAGE_KEYS.outbox, JSON.stringify(seed.outbox))
  const fake = new FakeFetch()
  let n = 0
  const client = new ChatClient({
    storage,
    fetchFn: fake.fn,
    baseUrl: 'http://server',
    randomUUID: () => uuid(0x2000 + ++n),
  })
  clients.push(client)
  render(<App client={client} />)
  return { storage, fake, client }
}

/** Lets the engine's promise chains run inside act(). */
async function settle(): Promise<void> {
  await act(async () => {
    for (let i = 0; i < 10; i++) await Promise.resolve()
    await new Promise((r) => setTimeout(r, 0))
  })
}

async function respond(call: FakeCall, status: number, body: unknown): Promise<void> {
  await act(async () => call.respond(status, body))
  await settle()
}

const byId = (id: string) => screen.getByTestId(id)
const queryId = (id: string) => screen.queryByTestId(id)

function type(id: string, value: string): void {
  fireEvent.change(byId(id), { target: { value } })
}

afterEach(() => {
  for (const c of clients) c.engine.stop()
  clients = []
  cleanup()
})

describe('Login and identity', () => {
  it('REQ-ID-001 without a persisted identity shows Login and the engine does not run', async () => {
    const { fake, client } = setup()
    await settle()
    expect(byId('login-name')).toHaveProperty('placeholder', 'Your name')
    expect(byId('login-submit').textContent).toBe('Continue')
    expect(queryId('login-error')).toBeNull()
    expect(client.engine.isRunning()).toBe(false)
    expect(fake.calls).toHaveLength(0)
  })

  it('REQ-ID-001 with a persisted identity shows Conversations directly and starts the engine', async () => {
    const { fake, client } = setup({ identity: 'Alice' })
    await settle()
    expect(byId('me-name').textContent).toBe('Alice')
    expect(client.engine.isRunning()).toBe(true)
    expect(fake.calls).toHaveLength(1)
  })

  it('REQ-ID-002 an invalid name stays on Login with the exact error and persists nothing', async () => {
    const { storage, fake } = setup()
    for (const name of ['   ', 'bad name!', '\u0085Alice', 'a'.repeat(33)]) {
      type('login-name', name)
      fireEvent.click(byId('login-submit'))
      expect(byId('login-error').textContent).toBe("Name must be 1-32 characters: letters, digits, '_' or '-'.")
      expect(queryId('me-name')).toBeNull()
    }
    await settle()
    expect(storage.data.size).toBe(0)
    expect(fake.calls).toHaveLength(0)
  })

  it('REQ-ID-003 REQ-ID-006 a valid login persists the normalized name and opens Conversations', async () => {
    const { storage, client, fake } = setup()
    type('login-name', '　 Alice ﻿')
    fireEvent.submit(byId('login-name').closest('form')!)
    expect(storage.getItem(STORAGE_KEYS.identity)).toBe('Alice')
    expect(byId('me-name').textContent).toBe('Alice')
    expect(client.engine.isRunning()).toBe(true)
    await settle()
    // Login itself made no request; only the engine's sync runs.
    expect(fake.calls.every((c) => c.method === 'GET')).toBe(true)
  })

  it('REQ-ID-004 REQ-ID-005 logout stops the engine, deletes all state, and a new login starts at cursor 0', async () => {
    const m = local({ to: 'Bob', body: 'queued one' })
    const { storage, fake, client } = setup({ identity: 'Alice', messages: [m], outbox: [m.id] })
    await settle()
    const inFlight = fake.only()
    fireEvent.click(byId('logout'))
    expect(inFlight.signal?.aborted).toBe(true)
    expect(client.engine.isRunning()).toBe(false)
    expect(storage.data.size).toBe(0)
    expect((byId('login-name') as HTMLInputElement).value).toBe('')

    type('login-name', 'Alice')
    fireEvent.click(byId('login-submit'))
    await settle()
    const probe = fake.only()
    expect(probe.method).toBe('GET')
    expect(new URL(probe.url).searchParams.get('after')).toBe('0')
    expect(byId('queued-count').textContent).toBe('0 queued')
  })
})

